    53	void aic_memheap_init(void) {
    54	  rt_ubase_t begin_align;
    55	  rt_ubase_t end_align;
    56	  int i = 0;
    57	
    58	  for (i = 0; i < sizeof(aic_memheaps) / sizeof(struct aic_memheap); i++) {
    59	    begin_align =
    60	        RT_ALIGN((rt_ubase_t)aic_memheaps[i].begin_addr, RT_ALIGN_SIZE);
    61	    end_align =
    62	        RT_ALIGN_DOWN((rt_ubase_t)aic_memheaps[i].end_addr, RT_ALIGN_SIZE);
    63	    RT_ASSERT(end_align > begin_align);
    64	
    65	    rt_memheap_init(&aic_memheaps[i].heap, aic_memheaps[i].name,
    66	                    (void *)begin_align, end_align - begin_align);
    67	    rt_mutex_init(&aic_memheaps[i].lock, aic_memheaps[i].name,
    68	                  RT_IPC_FLAG_PRIO);
    69	  }
    70	}
