    71	  uint32_t mxstatus = __get_MXSTATUS();
    72	  mxstatus |= (1 << 22);
    73	  /* enable mxstatus MM */
    74	  mxstatus |= (1 << 15);
    75	  __set_MXSTATUS(mxstatus);
    76	
    77	  /* enable mexstatus SPUSHEN/SPSWAPEN */
