#include "aic_soc.h"
#include "riscv_mtimer.h"

#define D13X_MTIMECMP          (E907_CORET_BASE + 0x0000UL)
#define D13X_MTIME             (E907_CORET_BASE + 0x7ff8UL)

#define D13X_UART_THR_OFF      0x00UL
#define D13X_UART_LSR_OFF      0x14UL
#define D13X_UART_LSR_THRE     0x20UL

#define D13X_BOOT_TIMER_FREQ   IHS_VALUE
#define D13X_PUTC_TIMEOUT      1000000

static inline uint32_t d13x_getreg32(uintptr_t addr)
{
  return *(volatile uint32_t *)addr;
}

static inline void d13x_putreg32(uint32_t value, uintptr_t addr)
{
  *(volatile uint32_t *)addr = value;
}

static void d13x_lowputc(int ch)
{
  uint32_t count = 0;

  while ((d13x_getreg32(UART0_BASE + D13X_UART_LSR_OFF) &
          D13X_UART_LSR_THRE) == 0)
    {
      if (++count > D13X_PUTC_TIMEOUT)
        {
          return;
        }
    }

  d13x_putreg32((uint32_t)ch, UART0_BASE + D13X_UART_THR_OFF);
  (void)d13x_getreg32(UART0_BASE + D13X_UART_LSR_OFF);
}

void up_allocate_heap(void **heap_start, size_t *heap_size)
{
  extern uintptr_t _sheap;
  extern uintptr_t _eheap;

  *heap_start = (void *)&_sheap;
  *heap_size = (size_t)((uintptr_t)&_eheap - (uintptr_t)&_sheap);
}

void up_timer_initialize(void)
{
  struct oneshot_lowerhalf_s *lower;

  /* Until CMU/PLL bring-up is added, assume the core timer runs from the
   * documented high-speed oscillator source used at early boot.
   */

  lower = riscv_mtimer_initialize(D13X_MTIME, D13X_MTIMECMP,
                                  RISCV_IRQ_MTIMER,
                                  (uint64_t)D13X_BOOT_TIMER_FREQ);

  DEBUGASSERT(lower != NULL);
  up_alarm_set_lowerhalf(lower);
}

void riscv_earlyserialinit(void)
{
}

void riscv_serialinit(void)
{
}

void up_putc(int ch)
{
  if (ch == '\n')
    {
      d13x_lowputc('\r');
    }

  d13x_lowputc(ch);
}

