#include <nuttx/config.h>

#include <stdint.h>

#include <nuttx/arch.h>
#include <nuttx/irq.h>

#include "riscv_internal.h"

#include "chip.h"

void up_irqinitialize(void)
{
  /* Disable interrupts while the core-side interrupt state is initialized. */

  up_irq_save();

#if defined(CONFIG_STACK_COLORATION) && CONFIG_ARCH_INTERRUPTSTACK > 15
  {
    size_t intstack_size = (CONFIG_ARCH_INTERRUPTSTACK & ~15);
    riscv_stack_color(g_intstackalloc, intstack_size);
  }
#endif

  /* Use the common NuttX RISC-V exception/trap handler entry. */

  riscv_exception_attach();

#ifndef CONFIG_SUPPRESS_INTERRUPTS
  riscv_color_intstack();
  up_irq_enable();
#endif
}

void up_enable_irq(int irq)
{
  if (irq == RISCV_IRQ_MSOFT)
    {
      SET_CSR(CSR_MIE, MIE_MSIE);
    }
  else if (irq == RISCV_IRQ_MTIMER)
    {
      SET_CSR(CSR_MIE, MIE_MTIE);
    }
  else if (irq == RISCV_IRQ_MEXT)
    {
      SET_CSR(CSR_MIE, MIE_MEIE);
    }
  else
    {
      /* Per-source CLIC programming is deferred until real device drivers
       * are added. The common M-mode external interrupt gate is handled in
       * up_irq_enable().
       */

      UNUSED(irq);
    }
}

void up_disable_irq(int irq)
{
  if (irq == RISCV_IRQ_MSOFT)
    {
      CLEAR_CSR(CSR_MIE, MIE_MSIE);
    }
  else if (irq == RISCV_IRQ_MTIMER)
    {
      CLEAR_CSR(CSR_MIE, MIE_MTIE);
    }
  else if (irq == RISCV_IRQ_MEXT)
    {
      CLEAR_CSR(CSR_MIE, MIE_MEIE);
    }
  else
    {
      UNUSED(irq);
    }
}

void riscv_ack_irq(int irq)
{
  UNUSED(irq);
}

irqstate_t up_irq_enable(void)
{
  irqstate_t oldstat;

  /* Keep machine external interrupts globally reachable. Timer/software
   * sources are enabled individually by up_enable_irq().
   */

  SET_CSR(CSR_MIE, MIE_MEIE);

  oldstat = READ_AND_SET_CSR(CSR_MSTATUS, MSTATUS_MIE);
  return oldstat;
}

void *riscv_dispatch_irq(uintreg_t vector, uintreg_t *regs)
{
  int irq = (int)(vector & RISCV_IRQ_MASK);

  if ((vector & RISCV_IRQ_BIT) != 0)
    {
      irq += RISCV_IRQ_ASYNC;
    }

  if (irq >= 0 && irq < NR_IRQS)
    {
      riscv_ack_irq(irq);
      regs = riscv_doirq(irq, regs);
    }

  return regs;
}

