static void up_set_freq(uint32_t baud, int clk_id) {
  int i;
  for (i = 0; uart_freq_baud_list[i].baud != 0; i++) {
    if (baud == uart_freq_baud_list[i].baud) {
      hal_clk_set_freq(clk_id, uart_freq_baud_list[i].freq);
      return;
    }
  }
}

