void d13x_chip_early_boot(void)
{
  /* Reserved for SRAM remap / clock / cache work once real init is added. */
}

void d13x_chip_late_boot(void)
{
  /* Reserved for drivers that must run after up_initialize(). */
}

void d13x_board_initialize(void)
{
