  struct aic_clk_comm_cfg comm;
  unsigned long rate;
  u8 id;
  u8 type;
  u8 parent_id;
  u8 flag;
};

/* Define types of pll */
enum aic_pll_type {
  AIC_PLL_INT, /* integer pll */
  AIC_PLL_FRA, /* fractional pll */
  AIC_PLL_SDM, /* spread spectrum pll */
};

struct aic_clk_pll_cfg {
  struct aic_clk_comm_cfg comm;
  u32 offset_gen;
  u32 offset_fra;
  u32 offset_sdm;
  u8 id;
  u8 type;
  u8 parent_id;
  u8 flag;
};

enum aic_fixed_parent_type {
  AIC_FPCLK_NORMAL,
  AIC_FPCLK_FIXED_FACTOR,
};

/*
 * This structure is designed for compatible with multiple dividers.
 * For example, CPU has three parent clocks: CLK_24M, PLL_INT0, PLL_INT1,
 * with corresponding frequency division coefficients of 1, (DIV + 1), 2,
 * respectively. If shift < 0, wd.div represents the frequency division. If
 * shift >= 0, wd.width represents the width of frequency division in register.
 */
struct table_div {
  s16 shift;
  union {
    u16 width;
    u16 div;
  } wd;
};

