  mxstatus = __get_MXSTATUS();
  mxstatus |= (1U << 22) | (1U << 15);
  __set_MXSTATUS(mxstatus);

  mexstatus = __get_MEXSTATUS();
  mexstatus &= ~((1U << 16) | (1U << 17));
