void riscv_serialinit(void)
{
  uart_register("/dev/console", &g_d13x_uart1port);
  uart_register("/dev/ttyS1", &g_d13x_uart1port);
}

void up_putc(int ch)
{
  FAR struct d13x_uart_s *priv = &g_d13x_uart1priv;
  irqstate_t flags;

  d13x_uart_hwinit(priv);

  flags = spin_lock_irqsave(&priv->lock);

  if (ch == '\n')
    {
      d13x_uart_lowputc(priv, '\r');
    }

  d13x_uart_lowputc(priv, ch);
  spin_unlock_irqrestore(&priv->lock, flags);
}

