static inline uint32_t d13x_uart_getreg32(uintptr_t addr)
{
  return *(volatile uint32_t *)addr;
}

static inline void d13x_uart_putreg32(uint32_t value, uintptr_t addr)
{
  *(volatile uint32_t *)addr = value;
}

static inline uintptr_t d13x_gpio_pincfg_addr(unsigned int group,
                                              unsigned int pin)
{
  return GPIO_BASE + (group * D13X_GPIO_GROUP_STRIDE) +
         D13X_GPIO_PINCFG_BASE + (pin * D13X_GPIO_PINCFG_STRIDE);
}

static void d13x_pinmux_config(unsigned int pin, unsigned int func,
                               unsigned int pull)
{
  uintptr_t addr;
  uint32_t val;

  addr = d13x_gpio_pincfg_addr(D13X_GPIO_GROUP_A, pin);
  val = d13x_uart_getreg32(addr);
  val &= ~((0x0fU << D13X_PINMUX_FUNC_SHIFT) |
           (0x07U << D13X_PINMUX_DRV_SHIFT) |
           (0x03U << D13X_PINMUX_PULL_SHIFT));
  val |= (func << D13X_PINMUX_FUNC_SHIFT) |
         (D13X_PINMUX_DRV_DEFAULT << D13X_PINMUX_DRV_SHIFT) |
         (pull << D13X_PINMUX_PULL_SHIFT);
  d13x_uart_putreg32(val, addr);
}

static void d13x_uart_clock_enable(void)
{
  uint32_t val;

  val = d13x_uart_getreg32(D13X_CMU_GPIO_REG);
  val |= D13X_CMU_GATE_BUS | D13X_CMU_RSTN;
  d13x_uart_putreg32(val, D13X_CMU_GPIO_REG);

  val = d13x_uart_getreg32(D13X_CMU_UART1_REG);
  val &= ~D13X_CMU_DIV_MASK;
  val |= ((D13X_CONSOLE_UART_CMU_DIV - 1U) << D13X_CMU_DIV_SHIFT);
  val |= D13X_CMU_GATE_MOD | D13X_CMU_GATE_BUS | D13X_CMU_RSTN;
  d13x_uart_putreg32(val, D13X_CMU_UART1_REG);
}

static void d13x_uart_hwinit(struct d13x_uart_s *priv)
{
  uint32_t lcr;

  if (priv->initialized)
    {
      return;
    }

  d13x_uart_clock_enable();

  d13x_pinmux_config(D13X_GPIO_PA2, D13X_PINMUX_UART_FUNC,
                     D13X_PINMUX_PULL_NONE);
  d13x_pinmux_config(D13X_GPIO_PA3, D13X_PINMUX_UART_FUNC,
                     D13X_PINMUX_PULL_UP);

  d13x_uart_putreg32(0, priv->base + D13X_UART_IER_OFF);

  lcr = D13X_UART_LCR_DLAB;
  d13x_uart_putreg32(lcr, priv->base + D13X_UART_LCR_OFF);
  d13x_uart_putreg32(D13X_CONSOLE_UART_DIVISOR & 0xffU,
                     priv->base + D13X_UART_DLL_OFF);
  d13x_uart_putreg32((D13X_CONSOLE_UART_DIVISOR >> 8) & 0xffU,
                     priv->base + D13X_UART_DLH_OFF);
  d13x_uart_putreg32(D13X_UART_LCR_8N1, priv->base + D13X_UART_LCR_OFF);
  d13x_uart_putreg32(D13X_UART_FCR_FIFO_EN |
                     D13X_UART_FCR_RXRST |
                     D13X_UART_FCR_TXRST,
                     priv->base + D13X_UART_FCR_OFF);

  (void)d13x_uart_getreg32(priv->base + D13X_UART_LSR_OFF);
  (void)d13x_uart_getreg32(priv->base + D13X_UART_IIR_OFF);
  (void)d13x_uart_getreg32(priv->base + D13X_UART_USR_OFF);

  priv->initialized = true;
}

static void d13x_uart_lowputc(struct d13x_uart_s *priv, int ch)
{
  uint32_t count = 0;

  while ((d13x_uart_getreg32(priv->base + D13X_UART_LSR_OFF) &
          D13X_UART_LSR_THRE) == 0)
    {
      if (++count > D13X_UART_PUTC_TIMEOUT)
        {
          return;
        }
    }

  d13x_uart_putreg32((uint32_t)ch, priv->base + D13X_UART_THR_OFF);
  (void)d13x_uart_getreg32(priv->base + D13X_UART_LSR_OFF);
}

static int d13x_uart_setup(FAR struct uart_dev_s *dev)
{
  FAR struct d13x_uart_s *priv = dev->priv;

  d13x_uart_hwinit(priv);
  return OK;
}

