  uint32_t val;

  addr = d13x_gpio_pincfg_addr(D13X_GPIO_GROUP_A, pin);
  val = d13x_uart_getreg32(addr);
  val &= ~((0x0fU << D13X_PINMUX_FUNC_SHIFT) |
           (0x07U << D13X_PINMUX_DRV_SHIFT) |
           (0x03U << D13X_PINMUX_PULL_SHIFT));
  val |= (func << D13X_PINMUX_FUNC_SHIFT) |
         (D13X_PINMUX_DRV_DEFAULT << D13X_PINMUX_DRV_SHIFT) |
         (pull << D13X_PINMUX_PULL_SHIFT);
