static inline uint32_t d13x_uart_getreg32(uintptr_t addr)
{
  return *(volatile uint32_t *)addr;
}

static inline void d13x_uart_putreg32(uint32_t value, uintptr_t addr)
{
  *(volatile uint32_t *)addr = value;
}

static inline uintptr_t d13x_gpio_pincfg_addr(unsigned int group,
                                              unsigned int pin)
{
  return GPIO_BASE + (group * D13X_GPIO_GROUP_STRIDE) +
         D13X_GPIO_PINCFG_BASE + (pin * D13X_GPIO_PINCFG_STRIDE);
}

static void d13x_pinmux_config(unsigned int pin, unsigned int func,
                               unsigned int pull)
{
  uintptr_t addr;
  uint32_t val;

  addr = d13x_gpio_pincfg_addr(D13X_GPIO_GROUP_A, pin);
  val = d13x_uart_getreg32(addr);
  val &= ~((0x0fU << D13X_PINMUX_FUNC_SHIFT) |
           (0x07U << D13X_PINMUX_DRV_SHIFT) |
           (0x03U << D13X_PINMUX_PULL_SHIFT));
  val |= (func << D13X_PINMUX_FUNC_SHIFT) |
         (D13X_PINMUX_DRV_DEFAULT << D13X_PINMUX_DRV_SHIFT) |
         (pull << D13X_PINMUX_PULL_SHIFT);
  d13x_uart_putreg32(val, addr);
}

static void d13x_uart_clock_enable(void)
{
  uint32_t val;

  val = d13x_uart_getreg32(D13X_CMU_GPIO_REG);
  val |= D13X_CMU_GATE_BUS | D13X_CMU_RSTN;
  d13x_uart_putreg32(val, D13X_CMU_GPIO_REG);

  val = d13x_uart_getreg32(D13X_CMU_UART0_REG);
  val &= ~D13X_CMU_DIV_MASK;
  val |= ((D13X_CONSOLE_UART_CMU_DIV - 1U) << D13X_CMU_DIV_SHIFT);
  val |= D13X_CMU_GATE_MOD | D13X_CMU_GATE_BUS | D13X_CMU_RSTN;
  d13x_uart_putreg32(val, D13X_CMU_UART0_REG);
}

static void d13x_uart_hwinit(struct d13x_uart_s *priv)
{
  if (priv->initialized)
    {
      return;
    }

  /* tinySPL has already initialized UART0 for the same console.  Preserve
   * that state during early NuttX bring-up; direct CMU writes here can
   * silence the only debug channel before the first byte is printed.
   */

  priv->initialized = true;
}

static void d13x_uart_lowputc(struct d13x_uart_s *priv, int ch)
{
  /* Do not wait on LSR during early bring-up.  The tinySPL console proves
   * UART0 TX is usable, but this port's LSR readiness bits do not match the
   * current minimal driver assumptions and can block the only debug path.
   */

  d13x_uart_putreg32((uint32_t)ch, priv->base + D13X_UART_THR_OFF);
}

