#define D13X_BOOT_TIMER_FREQ   IHS_VALUE

static void d13x_raw_uart_putc(int ch)
{
  *(volatile uint32_t *)(UART0_BASE + 0x00) = (uint32_t)ch;
}

static void d13x_raw_uart_puts(const char *str)
{
  while (*str != '\0')
    {
      d13x_raw_uart_putc(*str++);
    }
}

static inline uint32_t d13x_getreg32(uintptr_t addr)
{
  return *(volatile uint32_t *)addr;
}

void up_allocate_heap(void **heap_start, size_t *heap_size)
{
  extern uintptr_t _sheap;
  extern uintptr_t _eheap;

  d13x_raw_uart_puts("H0\r\n");
  *heap_start = (void *)&_sheap;
  *heap_size = (size_t)((uintptr_t)&_eheap - (uintptr_t)&_sheap);
  d13x_raw_uart_puts("H1\r\n");
}

void up_timer_initialize(void)
{
  struct oneshot_lowerhalf_s *lower;

  /* Until CMU/PLL bring-up is added, assume the core timer runs from the
   * documented high-speed oscillator source used at early boot.
   */

  d13x_raw_uart_puts("T0\r\n");
  lower = riscv_mtimer_initialize(D13X_MTIME, D13X_MTIMECMP,
                                  RISCV_IRQ_MTIMER,
                                  (uint64_t)D13X_BOOT_TIMER_FREQ);
  d13x_raw_uart_puts("T1\r\n");

  DEBUGASSERT(lower != NULL);
  up_alarm_set_lowerhalf(lower);
  d13x_raw_uart_puts("T2\r\n");
}

