  switch (regs[REG_A0])
    {
      case SYS_restore_context:
        {
          riscv_restorecontext(tcb);
          break_critical_section();
        }
        break;

      case SYS_switch_context:
        {
          riscv_savecontext(g_running_task);
          riscv_restorecontext(tcb);
          break_critical_section();
        }
        break;

