{
  FAR struct d13x_uart_s *priv = dev->priv;
  uint32_t ier;

  ier = d13x_uart_getreg32(priv->base + D13X_UART_IER_OFF);
  if (enable)
    {
      ier |= D13X_UART_IER_ETBEI;
      d13x_uart_putreg32(ier, priv->base + D13X_UART_IER_OFF);
