 *
 * Input Parameters:
 *   buf    - The user allocated buffer to be filled.
 *   buflen - the size of the buffer.
 *   infd   - The file to read characters from
 *   outfd  - The file to each characters to.
 *
 * Returned values:
 *   On success, the (positive) number of bytes transferred is returned.
 *   EOF is returned to indicate either an end of file condition or a
 *   failure.
 *
 ****************************************************************************/

ssize_t readline_fd(FAR char *buf, int buflen, int infd, int outfd)
{
  UNUSED(outfd);

  struct readline_s vtbl;
  struct termios oldcfg;
  struct termios cfg;
  ssize_t ret;

  if (isatty(infd))
    {
      tcgetattr(infd, &cfg);
      oldcfg = cfg;
#ifdef CONFIG_READLINE_ECHO
      cfg.c_lflag &= ~ECHO;
#endif
      cfg.c_lflag &= ~ICANON;
      if (cfg.c_lflag != oldcfg.c_lflag)
        {
          tcsetattr(infd, TCSANOW, &cfg);
        }
    }

  /* Set up the vtbl structure */

  vtbl.vtbl.rl_getc  = readline_getc;
  vtbl.infd          = infd;

#ifdef CONFIG_READLINE_ECHO
  vtbl.vtbl.rl_putc  = readline_putc;
  vtbl.vtbl.rl_write = readline_write;
  vtbl.outfd         = outfd;
#endif

  /* The let the common readline logic do the work */

  ret = readline_common(&vtbl.vtbl, buf, buflen);

  if (isatty(infd) && (cfg.c_lflag != oldcfg.c_lflag))
    {
      tcsetattr(infd, TCSANOW, &oldcfg);
    }

  return ret;
}

