    {
      d13x_raw_uart_putnamehex(" epc=", (uint32_t)regs[REG_EPC]);
      d13x_raw_uart_putnamehex(" ra=", (uint32_t)regs[REG_X1]);
      d13x_raw_uart_putnamehex(" sp=", (uint32_t)regs[REG_X2]);

