#ifdef ARCH_RISCV_FPU
  uint32_t mstatus = __get_MSTATUS();
  mstatus |= (1 << 13);
  __set_MSTATUS(mstatus);
#endif

  /* enable mxstatus THEADISAEE */
  uint32_t mxstatus = __get_MXSTATUS();
  mxstatus |= (1 << 22);
  /* enable mxstatus MM */
  mxstatus |= (1 << 15);
  __set_MXSTATUS(mxstatus);

